sys_ui_action.client_script_v2:
function onClick(g_form) {
    console.log('[SMS CLIENT] UI Action clicked successfully.');

    // Gather local references strictly for initial phone number lookup
    var consumerId = g_form.getValue('consumer') || '';
    var contactId  = g_form.getValue('contact') || '';

    // Helper function to handle auto-clearing message banners with green success styling
    var showTimedBanner = function(message, isError, isSuccess, secondsToClear) {
        g_form.clearMessages();
        var bannerText = message + ' (Notification clearing in ' + secondsToClear + 's)';

        if (isError) {
            g_form.addErrorMessage(bannerText);    // Red banner
        } else if (isSuccess) {
            g_form.addSuccessMessage(bannerText); // Green banner
        } else {
            g_form.addInfoMessage(bannerText);    // Blue/Neutral info banner
        }

        setTimeout(function() {
            if (typeof g_form !== 'undefined' && g_form.clearMessages) {
                g_form.clearMessages();
            }
        }, secondsToClear * 1000);
    };

    var openModal = function(defaultPhone) {
        g_modal.showFields({
            title: 'Send SMS Notification',
            size: 'lg',
            fields: [
                { type: 'string', name: 'phone', label: 'Phone Number', mandatory: true, value: defaultPhone, disabled: true },
                { 
                    type: 'choice', 
                    name: 'reason', 
                    label: 'Reason for message', 
                    mandatory: true,
                    choices: [
                        { value: 'knowledge_sharing', displayValue: 'Knowledge Sharing' },
                        { value: 'appointment_reminder', displayValue: 'Appointment Reminder' },
                        { value: 'case_update', displayValue: 'Case Update' },
                        { value: 'follow_up', displayValue: 'Follow-up' },
                        { value: 'general_inquiry', displayValue: 'General Inquiry' },
                        { value: 'support_notification', displayValue: 'Support Notification' }
                    ]
                },
                { type: 'string', name: 'message', label: 'Message to send', mandatory: true }
            ]
        }).then(function(result) {
            console.log('[SMS CLIENT] Modal submitted. Preparing parameters...');

            // 1. Initializing Banner (Neutral Info banner, lasts 3 seconds)
            showTimedBanner('Initiating SMS message pipeline...', false, false, 3);

            var getVal = function(name, defaultValue) {
                if (result && result.updatedFields) {
                    var field = result.updatedFields.filter(function(f) { return f.name === name; })[0];
                    if (field) return field.value;
                }
                return defaultValue || '';
            };

            var reasonText       = getVal('reason', '');
            var messageText      = getVal('message', '');
            var interactionSysId = g_form.getUniqueValue();

            // Instantiate GlideAjax
            var ga = new GlideAjax('x_snc_pab_ee_tkit.SendSMSviaInteraction');
            ga.addParam('sysparm_name', 'executeSmsSubflow');
            ga.addParam('sysparm_interaction', interactionSysId);
            ga.addParam('sysparm_reason', reasonText);
            ga.addParam('sysparm_message', messageText);

            // Account/Contact/Consumer data handoff removed—subflow handles context lookup on server side

            ga.getXMLAnswer(function(response) {
                console.log('[SMS CLIENT] Server response returned: ' + response);

                try {
                    if (!response) {
                        showTimedBanner('Received empty (null) response from the server.', true, false, 5);
                        return;
                    }

                    var parsed = JSON.parse(response);

                    if (parsed && parsed.status === 'success') {
                        // 2. Completion Banner (Explicit Green Success banner, lasts 5 seconds)
                        var successMsg = parsed.notes ? 'SMS Status: ' + parsed.notes : 'SMS message has been sent successfully.';
                        showTimedBanner(successMsg, false, true, 5);
                        g_form.reload();
                    } else {
                        showTimedBanner(parsed.message || 'SMS subflow execution failed.', true, false, 5);
                    }
                } catch(err) {
                    showTimedBanner('An error occurred while processing the SMS server stream.', true, false, 5);
                }
            });
        });
    };

    // Smart phone lookup based on available party (Consumer vs Contact vs Fallback)
    if (consumerId) {
        g_form.getReference('consumer', function(cons) {
            var phoneNum = cons ? (cons.mobile_phone || cons.phone || '') : '';
            openModal(phoneNum);
        });
    } else if (contactId) {
        g_form.getReference('contact', function(con) {
            var phoneNum = con ? (con.mobile_phone || con.phone || '') : '';
            openModal(phoneNum);
        });
    } else {
        var fallbackPhone = g_form.getValue('phone') || g_form.getValue('callback_number') || '';
        openModal(fallbackPhone);
    }
}
